import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"聊天入口","description":"","frontmatter":{},"headers":[],"relativePath":"zh/channels.md","filePath":"zh/channels.md"}'),o={name:"zh/channels.md"};function n(l,e,d,r,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="聊天入口" tabindex="-1">聊天入口 <a class="header-anchor" href="#聊天入口" aria-label="Permalink to &quot;聊天入口&quot;">​</a></h1><p>你可以在平时使用的聊天软件中与 nanoMuse 对话，目前支持飞书 / Lark、钉钉、企业微信和 Telegram。用手机给机器人发消息，就能使用同一个 nanoMuse：每个聊天各自对应一段对话，回复会随生成进度显示，执行工具时会显示状态，需要审批时可以回复文字或点击按钮。开启「推送到这里」的聊天还会收到主动消息，包括问候、提醒、后台任务结果，以及需要你回答的问题。</p><p>这些入口都不需要公网地址。机器人会从你的网络内部主动建立长连接，让双方持续收发消息；Telegram 使用长轮询，也就是发送请求并等待新消息后再继续请求。因此，在路由器后面的电脑或笔记本上运行 nanoMuse 就可以使用。连接由各厂商的 SDK（软件开发工具包）处理，这些 SDK 是按需安装的可选依赖：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[feishu]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # lark-oapi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[dingtalk]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # dingtalk-stream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[wecom]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # wecom-aibot-sdk-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nanomuse[channels]&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # all three; Telegram needs nothing extra</span></span></code></pre></div><p>Docker 镜像已包含全部 SDK。未安装对应 SDK 时，应用会显示安装命令，并保持该入口的开关不变。</p><p>飞书或钉钉消息到达运行时（负责执行智能体任务的本地程序）后，如果处理失败，运行时日志会记录入口名称和错误。机器人显示已连接、却收到消息不回答时，可以先检查这份日志。</p><h2 id="where-to-find-it" tabindex="-1">设置入口 <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;设置入口 {#where-to-find-it}&quot;">​</a></h2><ul><li><p><strong>应用</strong>：进入设置 → 聊天入口。每种聊天软件各有一张卡片，包含开关、连接凭据、允许联系机器人的用户、已配对的聊天、每个聊天的「推送到这里」开关，以及「发一条测试消息」按钮。卡片还提供设置步骤和厂商控制台链接。</p></li><li><p><strong>终端</strong>：使用 <code>nanomuse channels status | pending | approve &lt;code&gt; | deny &lt;code&gt; | login feishu [--lark] | test &lt;name&gt;</code>。如果 <code>nanomuse serve</code> 正在运行，命令会调用它的 API（供程序访问功能的接口）；否则直接修改 <code>&lt;data_dir&gt;/channels/</code> 中的文件，由服务在启动或点击「重新加载」时读取。</p></li><li><p><strong>API</strong>：提供 <code>GET /api/channels</code>、<code>PUT /api/channels/&lt;name&gt;</code>、<code>POST /api/channels/pairing/&lt;code&gt;/approve|deny</code>、<code>PUT|DELETE /api/channels/&lt;name&gt;/chats/&lt;sender&gt;</code>、<code>POST /api/channels/&lt;name&gt;/test</code>、<code>POST /api/channels/deliver {text}</code>、<code>POST /api/channels/reload</code>。飞书另有 <code>POST /api/channels/feishu/login</code> 和 <code>GET /api/channels/feishu/login/&lt;device_code&gt;</code>。</p></li><li><p><strong>config.toml</strong>：手动配置服务器时，也可以添加 <code>[channels.&lt;name&gt;]</code> 配置段：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">channels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">telegram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${TELEGRAM_BOT_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_from = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123456789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Telegram user ids that never need a code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">group_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mention&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or &quot;open&quot;</span></span></code></pre></div><p>每个字段都以应用中保存的值为优先。在应用中输入的密钥会存入保险库（专门保存敏感凭据的位置），文件中只留下 <code>{{vault:CHANNEL_TELEGRAM_BOT_TOKEN}}</code> 这样的占位符。保存后不会再次显示密钥，字段只提示是否已设置。</p></li></ul><h2 id="setting-up-each-app" tabindex="-1">配置各聊天软件 <a class="header-anchor" href="#setting-up-each-app" aria-label="Permalink to &quot;配置各聊天软件 {#setting-up-each-app}&quot;">​</a></h2><p>下面使用的是 2026 年各厂商控制台的名称，厂商之后可能调整位置或名称。</p><h3 id="feishu-lark" tabindex="-1">飞书 / Lark <a class="header-anchor" href="#feishu-lark" aria-label="Permalink to &quot;飞书 / Lark {#feishu-lark}&quot;">​</a></h3><p>你可以在应用中点击「扫码创建机器人」，用飞书扫描并确认。也可以运行 <code>nanomuse channels login feishu</code>，国际版 Lark 加上 <code>--lark</code>。完成后，App ID 和 Secret 会自动保存，聊天入口随即启用。这是飞书为个人智能体提供的扫码创建应用流程，创建的应用已经配置好机器人能力和长连接事件。</p><p>如果手动配置，打开 <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">https://open.feishu.cn/app</a>，Lark 则打开 <a href="https://open.larksuite.com/app" target="_blank" rel="noreferrer">https://open.larksuite.com/app</a>：</p><ol><li>选择「创建企业自建应用」→「添加应用能力」→「机器人」。</li><li>在「权限管理」中添加 <code>im:message</code>、<code>im:message.p2p_msg:readonly</code>、<code>im:message.group_at_msg:readonly</code> 和 <code>im:resource</code>，最后一项用于图片和文件。</li><li>在「事件与回调」中，将事件订阅方式设为「长连接」，添加 <code>im.message.receive_v1</code>；将回调方式也设为「长连接」，添加 <code>card.action.trigger</code>，用于处理审批按钮。</li><li>在「凭证与基础信息」中，将「App ID」和「App Secret」复制到 nanoMuse，选择 <em>feishu</em> 或 <em>lark</em>。如果没有在厂商控制台设置「Encrypt Key」和「Verification Token」，这两项留空。</li><li>进入「版本管理与发布」，创建版本并发布。</li></ol><p>回复以交互卡片发送，正文支持 Markdown 排版。文字生成过程中，应用会约每秒更新一次原卡片。你的消息上出现 👍，表示 nanoMuse 正在处理。在群聊中，只有 @ 机器人时才会收到回答。</p><h3 id="dingtalk" tabindex="-1">钉钉 <a class="header-anchor" href="#dingtalk" aria-label="Permalink to &quot;钉钉 {#dingtalk}&quot;">​</a></h3><p>打开 <a href="https://open-dev.dingtalk.com/" target="_blank" rel="noreferrer">https://open-dev.dingtalk.com/</a>：</p><ol><li>创建「企业内部应用」，进入「添加应用能力」，添加「机器人」。</li><li>将消息接收模式设为「Stream 模式」，不需要回调 URL（接收厂商推送请求的公网地址）。</li><li>在「凭证与基础信息」中复制「Client ID」（AppKey）和「Client Secret」（AppSecret）。</li><li>在「权限管理」中添加机器人发送消息的权限 <code>qyapi_robot_sendmsg</code>。这样，开启「推送到这里」的聊天即使没有等待回复的消息，也能接收主动推送。</li><li>发布版本，再将机器人加入群聊，或在通讯录中找到它。</li></ol><p>钉钉不支持编辑已发出的消息，因此回复会在生成完毕后整条发送。群聊中的机器人只能收到 @ 它的消息。</p><h3 id="wecom" tabindex="-1">企业微信 <a class="header-anchor" href="#wecom" aria-label="Permalink to &quot;企业微信 {#wecom}&quot;">​</a></h3><p>进入企业微信管理后台 → 安全与管理 → 智能机器人：</p><ol><li>点击「创建机器人」，选择「API 模式」，连接方式选择「长连接」。</li><li>将「Bot ID」和「Secret」复制到 nanoMuse。</li><li>将机器人加入需要接收消息的聊天，或让用户在通讯录中找到它。</li></ol><p>运行时会将长连接使用的主机 <code>openws.work.weixin.qq.com</code> 加入 <code>NO_PROXY</code>（不经过代理的地址列表），因为企业 HTTPS 代理通常无法转发这种连接。回复会通过同一条 socket 连接逐段发送，主动推送的消息采用 Markdown 格式。</p><p>运行时最多保留 1,000 个企业微信聊天的回复帧，即用于向该聊天继续发送回复的数据。如果某个聊天的回复帧已被清理，下一条等待发送的回复会一次完整发出，不再逐段更新。该聊天收到新消息后，会重新获得回复帧。</p><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram {#telegram}&quot;">​</a></h3><ol><li>在 Telegram 中找到「@BotFather」，发送 <code>/newbot</code>，将得到的 token（机器人访问令牌）复制到 nanoMuse。</li><li>私聊可以直接使用。群聊需要先添加机器人。BotFather 的「Group Privacy」默认开启，此时机器人只会收到 @ 它的消息和对它自己消息的回复，与 <em>mention</em> 策略一致。</li><li>如果运行 nanoMuse 的电脑无法访问 <code>api.telegram.org</code>，设置「代理」，格式为 <code>socks5://…</code> 或 <code>http://…</code>。</li></ol><p>回复先发送，再随文字生成不断编辑原消息。超过 Telegram 的 4096 字符限制时会拆分为多条。审批消息包含两个可直接点击的按钮。</p><h2 id="pairing-who-may-talk-to-the-bot" tabindex="-1">配对：决定谁能与机器人对话 <a class="header-anchor" href="#pairing-who-may-talk-to-the-bot" aria-label="Permalink to &quot;配对：决定谁能与机器人对话 {#pairing-who-may-talk-to-the-bot}&quot;">​</a></h2><p>任何找到机器人的人都能给它发消息，但只有你允许的人才能让 nanoMuse 处理消息。</p><ul><li>陌生人第一次私聊时，只会收到一个<strong>配对码</strong>，原消息不会交给 nanoMuse。配对码由六位字母和数字组成，不含容易混淆的 0/O/1/I，十分钟内有效。你可以在设置 → 聊天入口中批准，或运行 <code>nanomuse channels approve &lt;code&gt;</code>。对方会收到通知，此后发送的消息才会交给智能体。</li><li><strong>免配对的 ID</strong>（<code>allow_from</code>）：填入聊天平台的用户 id，这些用户无需配对码。单独填 <code>*</code> 会允许所有人，仅适合其他人无法访问的机器人。</li><li><strong>群聊</strong>：未获准的用户会被忽略，群内不会发送配对码。获准用户的消息在 <code>group_policy = &quot;mention&quot;</code> 时需要 @ 机器人，设为 <code>&quot;open&quot;</code> 则每条消息都会回答。每个群拥有独立对话，每条消息都附带发送者姓名。</li><li>在应用中「移除」已配对聊天，或从 <code>pairing.json</code> 删除该配对后，对方下次发消息时需要重新获取配对码。</li></ul><p>配对关系和配对码保存在 <code>&lt;data_dir&gt;/channels/pairing.json</code>。这是数据目录，不是工作区，因此智能体自己的文件工具无法修改哪些人可以与它对话。</p><h2 id="how-a-chat-maps-to-the-muse" tabindex="-1">聊天如何对应到 nanoMuse 对话 <a class="header-anchor" href="#how-a-chat-maps-to-the-muse" aria-label="Permalink to &quot;聊天如何对应到 nanoMuse 对话 {#how-a-chat-maps-to-the-muse}&quot;">​</a></h2><p>每个聊天对应智能体的一段独立对话，id 为 <code>channel-&lt;app&gt;-&lt;chat id&gt;</code>，在应用抽屉中的标题类似「飞书 · Ann」或「Telegram · Team」。聊天软件收到的消息与 nanoMuse 应用中输入的消息使用同一个处理入口，因此记忆、目标、哨兵（Sentinel，检查操作风险和权限的组件）及技能等能力相同。照片、文件、语音等附件会保存在工作区的 <code>attachments/</code> 目录，并附在消息上。</p><p>任务执行时：</p><ul><li>平台允许编辑消息时，回复会随模型输出逐段显示。</li><li>工具执行期间，同一条消息中会显示简短的斜体状态，例如「正在搜索网页」或「正在运行命令」，随后被回复文字替换。</li><li>哨兵要求你确认的<strong>审批</strong>会发送到聊天中。飞书和 Telegram 使用带「允许」「拒绝」按钮的卡片；钉钉和企业微信发送文字，让你回复关键词。<code>allow</code>、<code>yes</code>、<code>ok</code>、<code>允许</code>、<code>同意</code> 表示允许一次；<code>deny</code>、<code>no</code>、<code>拒绝</code>、<code>不行</code> 表示拒绝。效果与在 nanoMuse 应用中点击审批卡片相同。</li><li>任务生成的文件会在运行结束后发送，对应内部的构件事件。</li><li>nanoMuse 提出的<strong>问题</strong>也会发送到聊天中，你的下一条消息会作为回答。</li></ul><p>状态文字的语言由 <code>agent.language</code> 决定：<code>zh</code> 使用中文，<code>en</code> 使用英文，<code>auto</code> 同时提供两种语言。</p><h2 id="deliver-here" tabindex="-1">推送到这里 <a class="header-anchor" href="#deliver-here" aria-label="Permalink to &quot;推送到这里 {#deliver-here}&quot;">​</a></h2><p>为已配对聊天开启「推送到这里」后，它还会接收主动消息，也就是手机应用会显示为通知的那些事件：后台任务的最终回复，设置为安静的任务除外；等待你决定的审批，可直接在聊天中回答；以及需要你回答的问题。同一个 nanoMuse 可以推送到多个聊天，每个聊天独立设置。<code>POST /api/channels/deliver {&quot;text&quot;: …}</code> 会给所有启用推送的聊天发送文字，适合从脚本或提醒任务中调用。</p><h2 id="security" tabindex="-1">安全 <a class="header-anchor" href="#security" aria-label="Permalink to &quot;安全 {#security}&quot;">​</a></h2><ul><li>密钥存入保险库，API 不会返回原文，配置文件只保存占位符。日志包含厂商错误信息，不包含连接凭据。</li><li>只有已配对或在允许名单中的用户能让 nanoMuse 处理消息。陌生人私聊只会收到配对码，在群聊中则不会得到回应。审批卡片也只接受已配对用户的按钮操作。</li><li>从聊天入口作出的审批仅限本次，记录的理由会注明「来自飞书」等来源，不会保存为长期授权。</li><li>聊天入口的数据保存在智能体无法访问的数据目录中。</li><li>所有连接都由运行时主动向外建立，不需要开放接收端口，也不需要公网 URL。</li></ul><h2 id="troubleshooting" tabindex="-1">排查问题 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;排查问题 {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你看到的情况</th><th>原因及处理方法</th></tr></thead><tbody><tr><td>「未安装」</td><td>运行 nanoMuse 的电脑缺少 SDK。运行页面显示的命令，例如 <code>pip install &#39;nanomuse[feishu]&#39;</code>，再开启聊天入口</td></tr><tr><td>「还缺设置」</td><td>某个必填字段为空，卡片会指出具体字段</td></tr><tr><td>「出错」，并显示厂商错误信息</td><td>凭据未通过验证，或无法连接厂商。修正后关闭再开启入口，或再次点击「保存」</td></tr><tr><td>群里的机器人不回答</td><td>群策略为 <em>mention</em>，但消息没有 @ 机器人；或者发送者尚未配对，群内不会显示配对码</td></tr><tr><td>飞书有回复，但没有表情回应或审批按钮</td><td>缺少 <code>im:message.group_at_msg:readonly</code>、<code>im:resource</code>，或没有为长连接配置 <code>card.action.trigger</code></td></tr><tr><td>飞书提示「app secret invalid」</td><td>控制台重新生成过 App Secret，需要填入新的值</td></tr><tr><td>钉钉连接成功但收不到消息</td><td>接收模式未设为 <em>Stream</em>，或版本尚未发布</td></tr><tr><td>企业微信在代理环境中连接失败</td><td>socket 连接不经过 <code>HTTPS_PROXY</code>，对应主机必须能够直连</td></tr><tr><td>Telegram 提示 <code>Conflict: terminated by other getUpdates request</code></td><td>两处正在使用同一个 token 接收消息，例如另一个运行时或 webhook（接收消息的回调接口）。只保留一处</td></tr><tr><td>反复收到配对码</td><td>需要在十分钟内批准一个配对码，可用 <code>nanomuse channels pending</code> 查看待处理列表</td></tr><tr><td><code>nanomuse channels …</code> 提示服务器拒绝 token</td><td>config.toml 中的 <code>server.token</code> 与正在运行的服务器不一致，或命令需要使用与服务器相同的 <code>--config</code></td></tr></tbody></table><p><code>nanomuse channels status --json</code> 输出的数据与应用页面读取的相同。</p>`,43)])])}const g=a(o,[["render",n]]);export{k as __pageData,g as default};
